    \item \textbf{Imp. Results:}
    \begin{align*}
    & \text{i) Sine. Cosec = 1} \\
    & \text{ii) Cos. Sec = 1} \\
    & \text{iii) tan. Cot = 1} \\
    & \text{iv) Sin}^2 \theta + \text{Cos}^2 \theta = 1 \\
