    \end{align*}

    \item \textbf{Trigonometry Ratios of Standard Angles:}
    \[
    \begin{array}{c|c|c|c|c|c|c}
    \text{Ratio} & 0^\circ & 30^\circ & 45^\circ & 60^\circ & 90^\circ & 180^\circ & 270^\circ & 360^\circ \\
    \hline
