    \cos & 1 & \frac{\sqrt{3}}{2} & \frac{1}{\sqrt{2}} & \frac{1}{2} & 0 & -1 & 0 & 1 \\
    \tan & 0 & \frac{1}{\sqrt{3}} & 1 & \sqrt{3} & \infty & 0 & \infty & 0 \\
    \end{array}
    \]

    \item \textbf{Sign Convention:}
    \[
    \begin{array}{c|c|c|c}
    \text{Quadrant} & \sin & \cos & \tan \\
    \hline
    \text{I} & + & + & + \\
    \text{II} & + & - & - \\
    \text{III} & - & - & + \\
    \text{IV} & - & + & - \\
    \end{array}
    \]

    \item \textbf{Allied Angles:}
    \begin{align*}
    & \text{1) Sin (90}^\circ - \theta) = \cos \theta \\
    & \text{2) Cos (90}^\circ - \theta) = \sin \theta \\
    & \text{3) tan (90}^\circ - \theta) = \cot \theta \\
    & \text{4) Cot (90}^\circ - \theta) = \tan \theta \\
    & \text{5) Sec (90}^\circ - \theta) = \csc \theta \\
    & \text{6) Cosec (90}^\circ - \theta) = \sec \theta \\
    \end{align*}

    \item \textbf{Compound Angles:}
    \begin{align*}
    & \sin (A \pm B) = \sin A \cos B \pm \cos A \sin B \\
    & \cos (A \pm B) = \cos A \cos B \mp \sin A \sin B \\
    & \tan (A \pm B) = \frac{\tan A \pm \tan B}{1 \mp \tan A \tan B} \\
    \end{align*}

    \item \textbf{Multiple Angle and Sub Multiple Angle:}
    \begin{align*}
    & \sin 2A = 2 \sin A \cos A \\
    & \cos 2A = \cos^2 A - \sin^2 A \\
    & \tan 2A = \frac{2 \tan A}{1 - \tan^2 A} \\
    & \sin A = 2 \sin \left(\frac{A}{2}\right) \cos \left(\frac{A}{2}\right) \\
    & \cos A = \cos^2 \left(\frac{A}{2}\right) - \sin^2 \left(\frac{A}{2}\right) \\
    & \tan A = \frac{2 \tan \left(\frac{A}{2}\right)}{1 - \tan^2 \left(\frac{A}{2}\right)} \\
    \end{align*}

    \item \textbf{Triple Angle Formulae:}
    \begin{align*}
    & \text{i) } \sin 3\theta = 3 \sin \theta - 4 \sin^3 \theta \\
    & \text{ii) } \cos 3\theta = 4 \cos^3 \theta - 3 \cos \theta \\
    & \text{iii) } \tan 3\theta = \frac{3 \tan \theta - \tan^3 \theta}{1 - 3 \tan^2 \theta} \\
    \end{align*}

    \item \textbf{Factorization Formulae:}
    \begin{align*}
    & \sin C + \sin D = 2 \sin \left(\frac{C+D}{2}\right) \cos \left(\frac{C-D}{2}\right) \\
    & \sin C - \sin D = 2 \cos \left(\frac{C+D}{2}\right) \sin \left(\frac{C-D}{2}\right) \\
    & \cos C + \cos D = 2 \cos \left(\frac{C+D}{2}\right) \cos \left(\frac{C-D}{2}\right) \\
    & \cos C - \cos D = -2 \sin \left(\frac{C+D}{2}\right) \sin \left(\frac{C-D}{2}\right) \\
    \end{align*}

    \item \textbf{Defactorization Formulae:}
    \begin{align*}
    & 2 \sin A \cos B = \sin (A+B) + \sin (A-B) \\
    & 2 \cos A \cos B = \cos (A+B) + \cos (A-B) \\
    & 2 \sin A \sin B = \cos (A-B) - \cos (A+B) \\
    \end{align*}
\end{enumerate}

\subsection*{Co-ordinate Geometry (2D)}

\begin{enumerate}
    \item \textbf{Distance Formula:} \quad $(x_1, y_1)$, $(x_2, y_2)$
    \[
    \sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2}
    \]

    \item \textbf{Section Formula:} \quad $P(x, y) = \left(\frac{mx_2 + nx_1}{m+n}, \frac{my_2 + ny_1}{m+n}\right)$ \\
    \text{Internally} \\
    $Q(x, y) = \left(\frac{mx_2 - nx_1}{m-n}, \frac{my_2 - ny_1}{m-n}\right)$ \\
    \text{Externally}

    \item \textbf{Midpoint Formula:}
    \[
    \left(\frac{x_1 + x_2}{2}, \frac{y_1 + y_2}{2}\right)
    \]

    \item \textbf{Centroid of Triangle:} \quad $\left(\frac{x_1 + x_2 + x_3}{3}, \frac{y_1 + y_2 + y_3}{3}\right)$

    \item \textbf{Area of Triangle:} \quad $\Delta = \frac{1}{2} \left| x_1(y_2-y_3) + x_2(y_3-y_1) + x_3(y_1-y_2) \right|$

    \item \textbf{Slope of Straight Line:} \quad $m = \tan \theta$

    \item \textbf{One Point Form:} \quad $y - y_1 = m(x - x_1)$ \\
    \text{Slope Intercept Form:} \quad $y = mx + c$

    \item \textbf{Two Point Form:} \quad $\frac{y - y_1}{y_2 - y_1} = \frac{x - x_1}{x_2 - x_1}$

    \item \textbf{Intercept Form:} \quad $\frac{x}{a} + \frac{y}{b} = 1$

    \item \textbf{Normal Form:} \quad $x \cos \alpha + y \sin \alpha = p$

    \item \textbf{Slope of Line:} \quad $x \cos \alpha + y \sin \alpha = p$

    \item \textbf{Intersection of Two Lines:} \quad $l_1: a_1x + b_1y + c_1 = 0$, $l_2: a_2x + b_2y + c_2 = 0$

    \item \textbf{Angle Between Two Lines:} \quad $\tan \theta = \left| \frac{m_1 - m_2}{1 + m_1m_2} \right|$

    \item \textbf{If the Lines are Parallel:} \quad $m_1 = m_2$

    \item \textbf{If the Lines are Perpendicular:} \quad $m_1 \cdot m_2 = -1$

    \item \textbf{Length of Perpendicular:} \quad $\frac{|ax_1 + by_1 + c|}{\sqrt{a^2 + b^2}}$

    \item \textbf{Bisector Equations:} \quad $\frac{ax + by + c}{\sqrt{a^2 + b^2}} = \pm \frac{a'x + b'y + c'}{\sqrt{a'^2 + b'^2}}$

    \item \textbf{Distance Between Parallel Lines:} \quad $\frac{|c_1 - c_2|}{\sqrt{a^2 + b^2}}$

    \item \textbf{Homogeneous Equation:} \quad $ax^2 + 2hxy + by^2 = 0$

    \item \textbf{General Equation:} \quad $ax^2 + 2hxy + by^2 + 2gx + 2fy + c = 0$ \\
    \text{If } $h^2 - ab = 0$, \text{represents a pair of lines} \\
    \text{Point of Intersection} $(x, y) = \left(\frac{hf-bg}{ab-h^2}, \frac{gh-af}{ab-h^2}\right)$
\end{enumerate}

\subsection*{Co-ordinate Geometry (3D)}

